import assert from 'node:assert/strict';
import { makeSandbox, makeNode, allByClass } from './poc_dom.mjs';
const [app, raw] = process.argv.slice(2);
const {sandbox,store} = makeSandbox(app, () => ({}));
const shown=JSON.parse(raw);
shown.sources[0].conclusion="Создать две задачи и приписать уточнение к XR-3.";
shown.sources[0].proposals.push({id:"internal-attach",revision:1,outcome:"attach",target:"XR-3"});
shown.sources[1].conclusion="Удалить устаревший фрагмент: нет нужды.";
const feed=makeNode('div');
const pick={addr:'synthetic',on:true,ask:{kind:'agent',task:'XR-1',since:1,text:'Подготовил задачи, согласуй их описание.',prepared:shown}};
sandbox.preparedPickWire(feed,pick,shown);
assert.equal(allByClass(feed,'askfb').length,1);
const marks=allByClass(feed,'caskpick');
assert.equal(marks.length,2,'согласие должно относиться к черновику');
const taskLines=[...feed.querySelectorAll('p')].filter((p)=>sandbox.askPickText(p).includes('/prepared/'));
assert.equal(taskLines.length,2,"внутренние действия получили ссылки задач");
assert.ok(sandbox.askPickText(feed).includes(shown.sources[0].conclusion));
assert.ok(sandbox.askPickText(feed).includes(shown.sources[1].conclusion));
assert.equal(sandbox.askPickText(feed).includes("/prepared/c"),false);
assert.equal(sandbox.askPickText(feed).includes("/prepared/internal-attach"),false);
assert.ok(taskLines.every((line)=>!allByClass(line,'caskpick').length),'при задачах остались галки');
const comment = sandbox.proposalComment(pick.proposalDraft);
assert.equal(comment.mode, 'comment');
assert.equal(comment.snapshots.length, 2);
assert.equal(comment.decisions.length, 0);
const click={stopPropagation(){}};
marks[0].handlers.click(click);
const saved=JSON.parse(store.get('devkit.askdraft.synthetic'));
assert.equal(saved.proposalDraft.decisions.length,3);
assert.ok(saved.proposalDraft.decisions.every((d)=>d.source==='XR-1' && d.action==='accept'));
const feed2=makeNode('div');
sandbox.preparedPickWire(feed2,pick,shown);
const again=allByClass(feed2,'caskpick');
assert.equal(again.length,2);
assert.equal(again[0].classList.contains('on'),true);
assert.equal(again[1].classList.contains('on'),false);
shown.sources[0].basis='новый';
const answer=sandbox.proposalAnswer(saved.proposalDraft);
assert.equal(answer.snapshots[0].digest,'old');
assert.equal(answer.snapshots[0].revision,shown.sources[0].revision);
assert.equal(answer.decisions.length,3);
// Сохранённая частичная отметка прежнего UI не означает согласие на весь разбор.
pick.proposalDraft.decisions.pop();
const feed3=makeNode('div');
sandbox.preparedPickWire(feed3,pick,pick.proposalDraft.shown);
assert.equal(allByClass(feed3,'caskpick')[0].classList.contains('on'),false);
assert.equal(pick.proposalDraft.decisions.length,0);
const onlyOps={...shown,anchor:"XR-2",sources:[shown.sources[1]]};
const opsFeed=makeNode("div");
const opsPick={addr:"synthetic-ops",on:true,ask:{...pick.ask,prepared:onlyOps}};
sandbox.preparedPickWire(opsFeed,opsPick,onlyOps);
assert.ok(sandbox.askPickText(opsFeed).includes(onlyOps.sources[0].conclusion));
assert.equal(sandbox.askPickText(opsFeed).includes("/prepared/"),false);
const opsMarks=allByClass(opsFeed,"caskpick"); assert.equal(opsMarks.length,1);
opsMarks[0].handlers.click(click);
assert.equal(sandbox.proposalAnswer(opsPick.proposalDraft).decisions[0].proposal,"c");
console.log('proposal whole source marks, conclusions, add-only links and persistence: ok');

sandbox.chatFeedIn("worktree");
const canonical=structuredClone(shown);
canonical.sources=[canonical.sources[0]];
canonical.sources[0].proposals[0].board_id="XR-16";
canonical.sources[0].proposals[0].title="Первая задача";
canonical.sources[0].proposals[1].board_id="XR-17";
canonical.sources[0].proposals[1].title="Вторая задача";
canonical.sources[0].conclusion="Предлагаю две задачи и приписку.\n\n### Состав разбора\n\n- Создать [XR-16](#worktree/draft/XR-1/prepared/a) - Первая задача\n\n- Создать [XR-17](#worktree/draft/XR-1/prepared/b) - Вторая задача\n\n- Приписать к XR-3";
const canonicalAsk={...pick.ask,text:"Подготовил заключение разбора и задачи. Согласуй весь результат.",prepared:canonical};
for (const existingMessage of [false,true]) {
  const canonicalFeed=makeNode("div");
  if (existingMessage) {
    const msg=makeNode("div");msg.className="msg";
    const bb=makeNode("div");bb.className="bb";
    bb.append(sandbox.mdRender(canonicalAsk.text+"\n\n"+canonical.sources[0].conclusion,"worktree"));
    msg.append(bb);canonicalFeed.append(msg);
  }
  const canonicalPick={addr:"canonical-"+existingMessage,on:true,ask:canonicalAsk};
  sandbox.preparedPickWire(canonicalFeed,canonicalPick,canonical);
  assert.equal(allByClass(canonicalFeed,"askfb").length,existingMessage?0:1,"канонический состав не распознан в реплике");
  const links=canonicalFeed.querySelectorAll("a").filter(a=>String(a.href).includes("/prepared/"));
  assert.deepEqual(links.map(a=>a.href).sort(),["#worktree/draft/XR-1/prepared/a","#worktree/draft/XR-1/prepared/b"],"дублируются ссылки задач в составе и fallback");
  assert.deepEqual(links.map(a=>a.textContent).sort(),["XR-16","XR-17"],"вместо номера показан служебный ключ");
  const whole=allByClass(canonicalFeed,"caskpick");assert.equal(whole.length,1);
  whole[0].handlers.click(click);
  const decisions=sandbox.proposalAnswer(canonicalPick.proposalDraft).decisions;
  assert.equal(decisions.length,3,"состав Ask потерял add или attach");
  assert.deepEqual(Array.from(decisions,d=>d.proposal).sort(),["a","b","internal-attach"]);
}
console.log("canonical prepared href matches actual widget and fallback without duplicate add links: ok");
